import { randomUUID } from 'node:crypto';
import { and, desc, eq, isNull, sql } from 'drizzle-orm';
import type request from 'supertest';
import { testItems } from './test-items.tables.js';
import { TEST_ITEM } from './test-item.record.js';
import { fieldSamples } from '../../../src/platform/fields/fields.js';
import { describeCapabilities } from '../../record-capabilities.js';
import { bootApp, type TestApp } from '../../support.js';

/**
 * Test items: the standard routes, on bodies from the declaration (fieldSamples):
 * a field added later is covered. Generated by `pnpm feature:add` (tools/feature): add the feature's own rules as tests here.
 */
describe('test items (e2e)', () => {
  let node: TestApp;

  beforeEach(async () => {
    node = await bootApp();
  });
  afterEach(() => node.close());

  const samples = fieldSamples(TEST_ITEM.fields);
  /** A change of one field. */
  const changed = samples.changed;
  const create = (
    agent: request.Agent,
    key = randomUUID(),
    sent = samples.body(),
  ) => agent.post('/v1/test-items').set('Idempotency-Key', key).send(sent);

  it('refuses a create without an Idempotency-Key (IDEMPOTENCY=required, the default)', async () => {
    const refused = await node
      .admin()
      .post('/v1/test-items')
      .send(samples.body())
      .expect(400);
    expect(refused.body).toMatchObject({ code: 'IDEMPOTENCY_KEY_REQUIRED' });
  });

  // On a record's create, which every app with a feature has (the app alone
  // may have none: CI's template-without-notes).
  it('documents Idempotency-Key as required where the deployment demands it (IDEMPOTENCY=required, the default)', async () => {
    const document = (await node.http().get('/api-json').expect(200)).body as {
      paths: Record<
        string,
        Record<string, { parameters?: { name: string; required?: boolean }[] }>
      >;
    };
    const header = document.paths['/v1/test-items']!.post!.parameters!.find(
      (parameter) => parameter.name === 'Idempotency-Key',
    );
    expect(header?.required).toBe(true);
  });

  it('creates once per Idempotency-Key, changes with If-Match (audited), deletes', async () => {
    const admin = node.admin();
    const key = randomUUID();
    const sent = samples.body();
    const created = await create(admin, key, sent).expect(201);
    const id = created.body.id as string;
    // The same key again: the first answer, not a second record.
    expect((await create(admin, key, sent)).body.id).toBe(id);

    const shown = await admin.get(`/v1/test-items/${id}`).expect(200);
    const etag = shown.headers.etag as string;
    const updated = await admin
      .patch(`/v1/test-items/${id}`)
      .set('If-Match', etag)
      .send(changed)
      .expect(200);
    expect(updated.body[samples.changedField]).toEqual(
      changed[samples.changedField],
    );
    // The ETag read before the change no longer matches.
    await admin
      .patch(`/v1/test-items/${id}`)
      .set('If-Match', etag)
      .send(changed)
      .expect(412);
    const actions = (await node.auditEntries({ targetId: id })).map(
      (entry) => entry.action,
    );
    expect(actions).toEqual(
      expect.arrayContaining(['testItem.created', 'testItem.updated']),
    );

    await admin.delete(`/v1/test-items/${id}`).expect(204);
    await admin.get(`/v1/test-items/${id}`).expect(404);
  });

  it('refuses a body that fails the schema', async () => {
    await node
      .admin()
      .post('/v1/test-items')
      .set('Idempotency-Key', randomUUID())
      .send({ ...samples.body(), ...samples.invalid })
      .expect(400);
  });

  it('lets each role do what it grants: editors their own, viewers read', async () => {
    const writer = await node.user(['editor']);
    const other = await node.user(['editor']);
    const viewer = await node.user(['viewer']);
    const id = (await create(writer.agent).expect(201)).body.id as string;
    // Not theirs to read: the 404 of a missing one (record-capabilities.ts tests every route).
    await other.agent.get(`/v1/test-items/${id}`).expect(404);
    expect(
      (await other.agent.get('/v1/test-items').expect(200)).body.items,
    ).toEqual([]);
    await viewer.agent.get(`/v1/test-items/${id}`).expect(200);
    await create(viewer.agent).expect(403);
  });

  it('keeps tenants apart', async () => {
    const id = (await create(node.admin()).expect(201)).body.id as string;
    const other = await node.otherTenant();
    await other.admin.get(`/v1/test-items/${id}`).expect(404);
  });

  it('lists newest first', async () => {
    const admin = node.admin();
    await create(admin).expect(201);
    const newest = (await create(admin).expect(201)).body.id as string;
    const page = await admin
      .get('/v1/test-items?sort=-createdAt&limit=10')
      .expect(200);
    expect(page.body.items[0].id).toBe(newest);
    expect(page.body.items).toHaveLength(2);
  });

  describe('relationships (parentId, record-relations.ts)', () => {
    const child = (agent: request.Agent, parentId: string | null) =>
      create(agent, randomUUID(), { ...samples.body(), parentId });

    it('describes the records that refer to a subject as its related panels', async () => {
      const described = await node
        .admin()
        .get('/v1/lists/TestItem')
        .expect(200);
      expect(described.body.related).toEqual([
        {
          subject: 'TestItem',
          path: 'test-items',
          field: 'parentId',
          title: 'title',
          required: false,
          onDelete: 'restrict',
        },
        {
          subject: 'TestItem',
          path: 'test-items',
          field: 'linkedId',
          title: 'title',
          required: false,
          onDelete: 'keep',
        },
      ]);
    });

    it("lists a record's related ones by the reference, only those the caller may read", async () => {
      const writer = await node.user(['editor']);
      const other = await node.user(['editor']);
      const viewer = await node.user(['viewer']);
      const parent = (await create(writer.agent).expect(201)).body.id as string;
      const mine = (await child(writer.agent, parent).expect(201)).body
        .id as string;
      await create(node.admin()).expect(201); // no parent: not related
      const related = (agent: request.Agent) =>
        agent
          .get(`/v1/test-items?parentId=${parent}&count=true`)
          .expect(200)
          .then(
            (page) => page.body as { items: { id: string }[]; total: number },
          );
      expect(await related(viewer.agent)).toMatchObject({
        items: [{ id: mine }],
        total: 1,
      });
      // Editors read their own only: someone else's children aren't theirs.
      expect((await related(other.agent)).items).toEqual([]);
    });

    it('refuses a reference to a record the writer may not read, in the recycle bin or of another tenant', async () => {
      const writer = await node.user(['editor']);
      const other = await node.user(['editor']);
      const theirs = (await create(other.agent).expect(201)).body.id as string;
      const refused = await child(writer.agent, theirs).expect(422);
      expect(refused.body).toMatchObject({
        code: 'reference_not_found',
        field: 'parentId',
      });
      await child(writer.agent, randomUUID()).expect(422);

      const mine = (await create(writer.agent).expect(201)).body.id as string;
      const kid = (await child(writer.agent, null).expect(201)).body
        .id as string;
      const etag = (await writer.agent.get(`/v1/test-items/${kid}`)).headers
        .etag as string;
      await writer.agent
        .patch(`/v1/test-items/${kid}`)
        .set('If-Match', etag)
        .send({ parentId: theirs })
        .expect(422);
      await writer.agent.delete(`/v1/test-items/${mine}`).expect(204);
      await child(writer.agent, mine).expect(422);

      const tenant = await node.otherTenant();
      const foreign = (await create(tenant.admin).expect(201)).body
        .id as string;
      await child(node.admin(), foreign).expect(422);
    });

    it('keeps a `keep` reference while its record is in the recycle bin, and after a restore', async () => {
      const admin = node.admin();
      const linked = (await create(admin).expect(201)).body.id as string;
      const kid = (
        await create(admin, randomUUID(), {
          ...samples.body(),
          linkedId: linked,
        }).expect(201)
      ).body.id as string;
      await admin.delete(`/v1/test-items/${linked}`).expect(204);
      expect(
        (await admin.get(`/v1/test-items/${kid}`).expect(200)).body.linkedId,
      ).toBe(linked);
      // Changing another field doesn't check the reference again.
      const etag = (await admin.get(`/v1/test-items/${kid}`)).headers
        .etag as string;
      await admin
        .patch(`/v1/test-items/${kid}`)
        .set('If-Match', etag)
        .send(changed)
        .expect(200);
      // Nor does restoring the record it refers to, or the referring one.
      await admin.delete(`/v1/test-items/${kid}`).expect(204);
      await admin.post(`/v1/test-items/${kid}/restore`).expect(200);
      await admin.post(`/v1/test-items/${linked}/restore`).expect(200);
      expect(
        (await admin.get(`/v1/test-items?linkedId=${linked}`).expect(200)).body
          .items,
      ).toMatchObject([{ id: kid }]);
    });

    it('refuses deleting a record live ones refer to (`restrict`), and restoring one onto a record in the recycle bin', async () => {
      const admin = node.admin();
      const parent = (await create(admin).expect(201)).body.id as string;
      const kid = (await child(admin, parent).expect(201)).body.id as string;
      const refused = await admin
        .delete(`/v1/test-items/${parent}`)
        .expect(409);
      expect(refused.body).toMatchObject({
        code: 'record_referenced',
        subject: 'TestItem',
        field: 'parentId',
      });
      // A child in the recycle bin doesn't hold its (optional) parent back.
      await admin.delete(`/v1/test-items/${kid}`).expect(204);
      await admin.delete(`/v1/test-items/${parent}`).expect(204);
      const restoring = await admin
        .post(`/v1/test-items/${kid}/restore`)
        .expect(409);
      expect(restoring.body).toMatchObject({
        code: 'reference_deleted',
        field: 'parentId',
      });
      // The parent first, then the child: the relation is live again.
      await admin.post(`/v1/test-items/${parent}/restore`).expect(200);
      await admin.post(`/v1/test-items/${kid}/restore`).expect(200);
      expect(
        (await admin.get(`/v1/test-items?parentId=${parent}`).expect(200)).body
          .items,
      ).toMatchObject([{ id: kid }]);
    });

    it("reads a record's related page as one range of the reference's index, at most a page of the list's limit", async () => {
      const admin = node.admin();
      const parent = (await create(admin).expect(201)).body.id as string;
      await child(admin, parent).expect(201);
      await admin
        .get(`/v1/test-items?parentId=${parent}&limit=101`)
        .expect(400);
      // The related panel's query (RecordStore.findPage, `?parentId=`, newest first):
      // planned on the index the field declares, the tenant and the parent in its condition.
      const plan = await node.inTenant(() =>
        node.db.transaction(async (tx) => {
          // A tiny table must not flip the plan to a sequential scan.
          await tx.execute(sql`set local enable_seqscan = off`);
          const statement = tx
            .select({ id: testItems.id })
            .from(testItems)
            .where(
              and(eq(testItems.parentId, parent), isNull(testItems.deletedAt)),
            )
            .orderBy(desc(testItems.id))
            .limit(11)
            .getSQL();
          const result = await tx.execute(
            sql`explain (format json) ${statement}`,
          );
          return JSON.stringify(result.rows[0]);
        }),
      );
      expect(plan).toContain('"Index Name":"test_items_parent_id_idx"');
      expect(plan).toMatch(/"Index Cond":"[^"]*tenant_id[^"]*parent_id/);
    });
  });

  // Each capability test-item.record.ts declares, its recycle bin and units (record-capabilities.ts).
  describeCapabilities(() => node, TEST_ITEM);
});
